class Solution {
  public boolean[] validSubarrays(int[] nums, int k, int[][] queries) {
    int n = nums.length, q = queries.length;
    java.util.Random rnd = new java.util.Random(20240607L);
    long[] hash = new long[100_001];
    for (int i = 0; i < hash.length; i++) hash[i] = rnd.nextLong();
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] ^ hash[nums[i]];
    // distinct counts per query, offline with a Fenwick tree over last occurrences
    int[] head = new int[n], next = new int[q];
    java.util.Arrays.fill(head, -1);
    for (int i = 0; i < q; i++) {
      next[i] = head[queries[i][1]];
      head[queries[i][1]] = i;
    }
    int[] bit = new int[n + 2], last = new int[100_001];
    java.util.Arrays.fill(last, -1);
    int[] distinct = new int[q];
    for (int r = 0; r < n; r++) {
      int v = nums[r];
      if (last[v] >= 0) for (int p = last[v] + 1; p <= n; p += p & -p) bit[p]--;
      for (int p = r + 1; p <= n; p += p & -p) bit[p]++;
      last[v] = r;
      for (int e = head[r]; e >= 0; e = next[e]) {
        int l = queries[e][0];
        int total = 0, below = 0;
        for (int p = r + 1; p > 0; p -= p & -p) total += bit[p];
        for (int p = l; p > 0; p -= p & -p) below += bit[p];
        distinct[e] = total - below;
      }
    }
    boolean[] ans = new boolean[q];
    for (int i = 0; i < q; i++)
      ans[i] = distinct[i] == k && pre[queries[i][1] + 1] == pre[queries[i][0]];
    return ans;
  }
}
